def uniform(points,count=180):
 p=np.asarray(points,float);p=np.vstack([p,p[0]]);d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))];u=np.linspace(0,d[-1],count,endpoint=False);return np.c_[np.interp(u,d,p[:,0]),np.interp(u,d,p[:,1])].tolist()
